CREATE SEQUENCE IF NOT EXISTS Pur_MPur_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Pur_MPur                             -- جدول ترويسة الشراء
( Id         BIGINT NOT NULL,				                  -- مفتاح رئيسي
  Period_Id  BIGINT NOT NULL,                          -- فترة العمل
  Status_Id  BIGINT Default 0 NOT NULL,                -- الحالة
