  Curn_Id    BIGINT NOT NULL,                          -- العملة
  Acc_Id     BIGINT NOT NULL,                          -- الحساب
  Doc_Id     BIGINT Default 0 NOT NULL,                -- نوع المستند
  BCurn_Id   BIGINT Default 1,                         -- عملة الأساس
  BCurn_Rate NUMERIC(25,8) Default 1,                      -- سعر الصرف
  Rel_Id     BIGINT,                                  -- مفتاح الأمر المشكل نتيجة تثبيت هذه الحركة
  Fin_Id     BIGINT,                                  -- مفتاح الورقة المالية
  Rate       BIGINT Default 0 NOT NULL,             -- سعر الصرف
  Num        BIGINT Default 0,                        -- الرقم
  dDate      TIMESTAMP NOT NULL,                               -- التاريخ
  DocN       VARCHAR(15),                                -- رقم المستند
  DocD       TIMESTAMP,                                        -- تاريخ المستند
  Rem        VARCHAR(100),          				        -- ملاحظات
  Ins_User   BIGINT, Ins_Date     TIMESTAMP,
  Upd_User   BIGINT, Upd_Date     TIMESTAMP,
  CONSTRAINT Pur_MPur_PK        PRIMARY KEY (Id)
);

