  nWidth     NUMERIC(25,2) Default 0,                      -- العرض
  nHeight    NUMERIC(25,2) Default 0,                      -- الارتفاع
  Barcode    VARCHAR(50),                           -- مسطرة الترميز
  LotSer     VARCHAR(50),                           -- طبخة/مسلسل
  SDate      TIMESTAMP,                                        -- تاريخ بداية
  EDate      TIMESTAMP,                                        -- تاريخ نهاية
  Rem        VARCHAR(100),          				        -- ملاحظات
  Ins_User   BIGINT, Ins_Date     TIMESTAMP,
  Upd_User   BIGINT, Upd_Date     TIMESTAMP,
  CONSTRAINT Pur_TPur_PK       PRIMARY KEY (Id)
);

